/* GENERATED by src/agents/unit_test_agent - review before relying on it.
 *
 * Requirement FR-018: On power-up or reset, the firmware shall display the CraftifAI logo on the OLED for 2 seconds before displaying sensor data or a heading, then switch to the Vehicle Parameters screen.
 * Verified by: hardware / instrument
 * Derived from: firmware/app/app.c, firmware/platforms/stm32/platform_io.c, firmware/services/display.c
 * Rationale: For FR-018-01, the assertions check the logo-page transfers and splash state at 100 ms, verify no other page is transferred through 1999 ms, and verify the transition at 2000 ms, matching display_process() lines 117–151 and its use of display_logo. For FR-018-02, the assertions check the post-splash dashboard transfer and that display_init() followed by processing starts a fresh logo splash; displ
 */

#include "unity.h"
#include "mock_platform_io.h"
#include "mock_sh1106.h"
#include "display.h"
#include "logo.h"

#include <stdbool.h>
#include <stdint.h>

static unsigned int page_calls;
static uint8_t logo_page_mask;
static bool all_pages_are_logo;
static uint8_t last_page;

static bool record_page(sh1106_send_t send, uint8_t address, uint8_t page,
                        const uint8_t *pixels, int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    page_calls++;
    last_page = page;
    if ((page < 8U) && (pixels == &display_logo[(uint16_t)page * 128U]))
    {
        logo_page_mask |= (uint8_t)(1U << page);
    }
    else
    {
        all_pages_are_logo = false;
    }
    return true;
}

static void configure_mocks(void)
{
    platform_io_log_Ignore();
    platform_io_now_ms_IgnoreAndReturn(100U);
    sh1106_init_IgnoreAndReturn(true);
    sh1106_enable_IgnoreAndReturn(true);
    sh1106_page_StubWithCallback(record_page);
}

static bool start_logo_splash(uint32_t init_ms, uint32_t process_ms,
                              const sensors_snapshot_t *readings)
{
    if (!display_init(init_ms))
    {
        return false;
    }
    page_calls = 0U;
    logo_page_mask = 0U;
    all_pages_are_logo = true;
    display_process(process_ms, readings);
    return display_is_splash();
}

void setUp(void)
{
    page_calls = 0U;
    logo_page_mask = 0U;
    all_pages_are_logo = true;
    last_page = 0U;
}

void tearDown(void)
{
}

void test_FR_018_01(void)
{
    sensors_snapshot_t readings = {0};
    configure_mocks();

    TEST_ASSERT_TRUE(start_logo_splash(0U, 100U, &readings));
    TEST_ASSERT_EQUAL_INT(8, page_calls);
    TEST_ASSERT_EQUAL_INT(0xFF, logo_page_mask);
    TEST_ASSERT_TRUE(all_pages_are_logo);

    /* The logo must remain the only transferred content until the 2 s boundary. */
    display_process(1999U, &readings);
    TEST_ASSERT_TRUE(display_is_splash());
    TEST_ASSERT_EQUAL_INT(8, page_calls);

    display_process(2000U, &readings);
    TEST_ASSERT_FALSE(display_is_splash());
    TEST_ASSERT_EQUAL_INT(9, page_calls);
    TEST_ASSERT_EQUAL_INT(0, last_page);
}

void test_FR_018_02(void)
{
    sensors_snapshot_t readings = {0};
    configure_mocks();

    TEST_ASSERT_TRUE(start_logo_splash(0U, 100U, &readings));
    display_process(2100U, &readings);
    TEST_ASSERT_FALSE(display_is_splash());
    TEST_ASSERT_EQUAL_INT(9, page_calls);
    TEST_ASSERT_EQUAL_INT(0, last_page);

    /* Reinitializing the display after normal operation must start the logo again. */
    TEST_ASSERT_TRUE(display_init(2200U));
    page_calls = 0U;
    logo_page_mask = 0U;
    all_pages_are_logo = true;
    display_process(2300U, &readings);
    TEST_ASSERT_TRUE(display_is_splash());
    TEST_ASSERT_EQUAL_INT(8, page_calls);
    TEST_ASSERT_EQUAL_INT(0xFF, logo_page_mask);
    TEST_ASSERT_TRUE(all_pages_are_logo);
}
